(function(){
'use strict';
const D=window.STUDIO_DATA,E=window.STUDIO_ENGINE,KEY='stage11-writing-studio-v3', $=id=>document.getElementById(id);
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=E.defaultState(),storageOK=true,recoveryRaw='',recoveryMessage='',selectedQuestion=0,selectedWord=0,selectedTaskUnit='all',reviewMode='vocabulary',reviewIndex=0,lastRouteHash='';
const pages=['home','plan','vocabulary','practice','develop','draft','progress','reference','teacher','tasks','review'];
function announce(message){$('announcer').textContent='';setTimeout(()=>$('announcer').textContent=message,30);}
function load(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(E.validateState(parsed))state=parsed;else{recoveryRaw=raw;recoveryMessage='An incompatible saved record was found. It has not been overwritten. Download the recovery backup before starting a new saved record.';storageOK=false;}}}catch(e){try{recoveryRaw=localStorage.getItem(KEY)||'';}catch(_){}storageOK=false;recoveryMessage='Saved work could not be read. This session remains usable. Download a backup to protect your work.';}
 if(state.timer.running){state.timer.remaining=Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000));state.timer.running=false;state.timer.deadline=null;}
}
function persist(){state.updatedAt=Date.now();if(!storageOK){$('saveStatus').textContent='Session only · download a backup';return;}try{localStorage.setItem(KEY,JSON.stringify(state));$('saveStatus').textContent='Saved in this browser';}catch(e){storageOK=false;$('saveStatus').textContent='Saving unavailable · back up now';announce('Local saving is unavailable. Your work remains in this session. Download a backup.');}}
let exportURL='';
function download(filename,content,type='text/plain'){if(exportURL)URL.revokeObjectURL(exportURL);exportURL=URL.createObjectURL(new Blob([content],{type}));$('exportLink').href=exportURL;$('exportLink').download=filename;$('exportLink').textContent='Save '+filename;$('exportText').value=content;$('exportDialog').showModal();announce('Export ready. Save the file or copy the export text.');}
function backup(){download('stage11-writing-backup.json',JSON.stringify(state,null,2),'application/json');}
function confirmClear(message,action){$('confirmMessage').textContent=message;const dialog=$('confirmDialog');dialog.returnValue='';dialog.onclose=()=>{if(dialog.returnValue==='confirm')action();};dialog.showModal();}
function currentGenre(){return D.genres[state.settings.genre];}
function currentPrompt(){const g=currentGenre();return g.prompts.find(p=>p.id===state.settings.prompt)||g.prompts[0];}
function draft(){const key=currentPrompt().id;if(!state.drafts[key])state.drafts[key]={text:'',versions:[],review:{},independent:false,updatedAt:Date.now()};return state.drafts[key];}
function plan(){const key=currentPrompt().id;if(!state.plans[key])state.plans[key]={focus:'',point:'',example:'',analysis:'',link:''};return state.plans[key];}
const isArgument=()=>['essay','healthEssay'].includes(state.settings.genre);
const isBio=()=>state.settings.genre==='biography';
const isFocusRoute=()=>['essay','biography'].includes(state.settings.genre);
function group(){return state.settings.genre+'-'+state.settings.pathway;}
function bank(){return isFocusRoute()?E.makeBank(state.settings.genre,state.settings.pathway):reviewBank();}
function answerKey(q){return q.id;}
function intro(label,title,description){return `<div class="page-intro"><p class="eyebrow">${h(label)}</p><h1>${title}</h1><p>${h(description)}</p></div>`;}
function scaffold(){return `<details><summary>Optional support · ${h(state.settings.pathway)}</summary><p>${state.settings.pathway==='foundation'?'Use these frames to get started. Change them to express your own ideas.':state.settings.pathway==='core'?'Check the purpose of each sentence. Use a frame only when it helps you express your own meaning.':'Evaluate the strength and limits of your evidence. Use these prompts flexibly; do not follow a mechanical formula.'}</p><ul>${currentGenre().frames.map(f=>`<li>${h(f)}</li>`).join('')}</ul></details>`;}
function home(){return `<div class="hero"><div class="hero-copy"><p class="eyebrow">YOUR IDEAS DESERVE A CLEAR VOICE</p><h1>Go beyond a point.<br><em>Give it purpose.</em></h1><p>Develop an idea. Explain why it matters. Support it with a relevant example, then connect it to your writing’s focus.</p><div class="actions"><a class="primary-link" href="#plan">Start your writing journey</a><a class="secondary-link" href="#draft">Continue your draft</a></div><p class="small muted" style="margin-top:18px">${h(currentGenre().name)} · ${h(state.settings.pathway)} pathway · ${state.settings.genre==='essay'?'UO 2.h':isBio()?'UO 1.g':'genre self-review'}</p></div><div class="hero-aside"><p class="eyebrow">A FLEXIBLE THINKING TOOL</p><div class="focus-chain"><div><small>01</small> Point</div><div><small>02</small> Explanation</div><div><small>03</small> Relevant example</div><div><small>04</small> Analysis</div><div><small>05</small> Link back</div></div><p>For essays, reconnect to your thesis. For biographies, show why the achievement or quality matters.</p></div></div><div class="section-top"><h2>Your next steps</h2><span class="badge">Plan → Practise → Develop → Draft → Review → Revise → Reflect</span></div><div class="journey-grid">${[
 ['plan','01 · PLAN','Find your focus','Choose your purpose, audience and central idea.'],['vocabulary','02 · INFER','Discover words in context','Predict first. Explain your clues. Transfer the meaning.'],['practice','03 · PRACTISE','Make language work','Check grammar, linkers, sentence order and examples.'],['develop','04 · DEVELOP','Build a meaningful paragraph','Explain your evidence and reconnect to the focus.'],['draft','05 · WRITE & REVISE','Make the draft your own','Review exact passages and compare revisions.'],['progress','06 · REFLECT','Notice your next step','Track practice separately from writing quality.']
 ].map(([url,n,title,text])=>`<a href="#${url}" class="journey-card"><span class="step">${n}</span><h3>${title}</h3><p>${text}</p></a>`).join('')}</div><div class="notice"><strong>You can revisit any step.</strong> Practice results never lock your learning. Browser checks are suggestions, not a comprehensive writing assessment.</div>${unitDirectory()}`;}
function unitDirectory(){return `<section class="panel"><div class="section-top"><h2>All units covered</h2><a href="#tasks">Browse all ${Object.values(D.genres).reduce((n,g)=>n+g.prompts.length,0)} writing tasks</a></div><p class="badge">${D.units.length} banks · ${D.units.reduce((n,u)=>n+u.vocab.length,0)} words · ${Object.keys(D.genres).length} writing formats · ${Object.values(state.answers).filter(a=>a.attempted).length} questions attempted · ${Object.values(state.drafts).filter(d=>d.text.trim()).length} saved drafts</p><p>Choose a unit for its vocabulary, writing formats and saved task drafts. The nine original unit banks remain available; Unit 1 adds the standards-mapped biography.</p><div class="journey-grid">${D.units.map(u=>{const gs=Object.values(D.genres).filter(g=>g.unitId===u.id);return `<article class="panel soft"><p class="eyebrow">${h(u.num)}</p><h3>${h(u.name)}</h3><p>${h(gs.map(g=>g.name).join(' · '))}</p><div class="actions"><a href="#tasks?unit=${u.id}">Writing tasks (${gs.reduce((n,g)=>n+g.prompts.length,0)})</a><a href="#vocabulary?unit=${u.id}">${u.vocab.length} words</a><a href="#review?unit=${u.id}">Quiz</a></div></article>`;}).join('')}</div></section>`;}
function tasksPage(){const entries=Object.entries(D.genres).filter(([k,g])=>selectedTaskUnit==='all'||g.unitId===selectedTaskUnit);return intro('ALL UNIT WRITING','Every format.<br>A task with purpose.','The 40 prompts from your reference are restored, alongside the existing focus tasks and new comparison, presentation, discussion and webpage tasks. Each exact task has its own saved plan, draft and revision history.')+`<section class="panel"><label for="taskUnit">Choose a unit<select id="taskUnit"><option value="all">All units</option>${D.units.map(u=>`<option value="${u.id}" ${u.id===selectedTaskUnit?'selected':''}>${h(u.num+' · '+u.name)}</option>`).join('')}</select></label></section>${entries.map(([key,g])=>`<section class="panel"><p class="eyebrow">${h(g.unit)}</p><h2>${h(g.name)}</h2><p>${h(g.purpose)}</p><p class="badge">${h(g.standards||'Genre self-review')} · ${h(g.register||'formal')} register</p><p class="help">Suggested length: ${h(g.wordRange||'200–250 words')}. Follow your teacher’s exact task instructions.</p><details><summary>Structure, useful choices & self-review</summary><p>These are flexible supports. No required linker count, sentence quota or compulsory hook establishes quality.</p><ol>${(g.structure||['Introduce the person and central focus','Develop achievements and challenges with verified examples','Explain qualities and significance']).map(x=>`<li>${h(x)}</li>`).join('')}</ol><p>Do: develop relevant examples, explain their significance and choose language for your reader. Avoid unsupported facts, lists without explanation and a mechanical paragraph formula.</p><ul>${(g.checklist||['Explain the central focus','Develop specific achievements and challenges','Connect their significance to the focus','Proofread and revise with evidence']).map(x=>`<li>${h(x)}</li>`).join('')}</ul><p>${g.register==='informal'?'Contractions and a friendly voice can suit an informal letter. Grammar and clarity still matter.':'Choose a consistent voice for this audience. First-person language may be appropriate when the task asks for a personal opinion or reflection.'}</p></details><ol>${g.prompts.map(p=>`<li style="margin:18px 0"><p>${h(p.text)}</p><div class="actions"><a class="primary-link" href="#draft?task=${encodeURIComponent(p.id)}&unit=${g.unitId}">${state.drafts[p.id]?.text?'Continue saved draft':'Write this task'}</a><a href="#plan?task=${encodeURIComponent(p.id)}&unit=${g.unitId}">Plan this task</a></div></li>`).join('')}</ol></section>`).join('')}`;}
function bindTasks(){on('taskUnit','change',e=>{location.hash='tasks?unit='+e.target.value;});}
const linkerQuiz=[
 ['The role gives pupils practical experience. ___, it supports local families.','In addition',['In addition','However','As a result'],'Addition introduces another benefit; it does not claim the second benefit is caused by the first.'],
 ['The project can help. ___, unsuitable roles may waste time.','However',['However','For example','Therefore'],'However marks the contrast between potential benefit and limitation.'],
 ['The team asked learners what they needed. ___, it designed more suitable activities.','As a result',['As a result','Nevertheless','For instance'],'The second action is presented as a consequence of asking.'],
 ['The volunteers prepared the books. ___, they welcomed the visitors.','Next',['Next','Although','For example'],'Next marks the sequence of actions.'],
 ['A mentor needs patience. ___, explaining one word several times can be necessary.','For example',['For example','In contrast','Therefore'],'This specific scenario illustrates the need for patience.'],
 ['___, pupils should choose a suitable role.','In my view',['In my view','Such as','As a result'],'In my view identifies a personal position. It does not make the position evidence-based.'],
 ['Diet and exercise both matter. ___ provides fuel; the latter builds fitness.','The former',['The former','The latter','These'],'The former refers to the first of the two named items: diet.'],
 ['___ the first task was difficult, the team continued.','Although',['Although','Therefore','For example'],'Although introduces a concession clause followed by a contrasting main clause.']
];
function reviewBank(){if(reviewMode==='vocabulary'){const u=vocabUnit();return u.vocab.map((v,i)=>({id:`review-vocabulary-${u.id}-${i}`,stem:`What does “${v.w}” mean in this context? ${v.transfer}`,answer:v.d,options:[v.d,...u.vocab.filter(x=>x.d!==v.d).slice(i%10,i%10+3).map(x=>x.d)].sort(),explanation:`${v.d} The clue “${v.evidence}” helps: ${v.clueExplanation}`,hint:v.clue,title:'Vocabulary in context',kind:'vocabulary'}));}if(reviewMode==='linkers')return linkerQuiz.map(([stem,answer,options,explanation],i)=>({id:'review-linkers-'+i,stem,answer,options,explanation,hint:'Identify the relationship between the ideas before choosing a phrase.',title:'Linkers in context',kind:'linkers'}));return Object.entries(D.genres).map(([key,g])=>({id:'review-writing-'+key,stem:`Which approach best suits ${g.name.toLowerCase()} (${g.unit})?`,answer:g.purpose,options:[g.purpose,...Object.entries(D.genres).filter(([k])=>k!==key).slice(0,2).map(([k,x])=>x.purpose)].sort(),explanation:`Purpose: ${g.purpose} Use ${g.register||'formal'} language suitable for the audience. Develop examples and explain their connection to the central focus.`,hint:'Think about the reader, genre and intended outcome.',title:'Writing genres',kind:'writing'}));}
function reviewPage(){const qs=reviewBank();reviewIndex=Math.min(Math.max(0,reviewIndex),qs.length-1);const q=qs[reviewIndex],a=state.answers[q.id]||{},done=qs.filter(x=>state.answers[x.id]?.attempted).length,score=qs.filter(x=>state.answers[x.id]?.firstCorrect).length;return intro('REVIEW QUIZZES','Recall in context.<br>Explain your choice.','Vocabulary, linker and writing-genre quizzes are restored. These scores describe closed-question practice only, not the quality of your original writing.')+`<section class="panel"><div class="input-grid"><label for="reviewMode">Quiz mode<select id="reviewMode">${[['vocabulary','Vocabulary'],['linkers','Linkers'],['writing','Writing genres']].map(([k,v])=>`<option value="${k}" ${k===reviewMode?'selected':''}>${v}</option>`).join('')}</select></label><label for="reviewUnit">Unit vocabulary<select id="reviewUnit">${D.units.map(u=>`<option value="${u.id}" ${u.id===vocabUnit().id?'selected':''}>${h(u.num+' · '+u.name)}</option>`).join('')}</select></label></div><p>${done}/${qs.length} attempted · ${score}/${done} correct on first attempt</p><label for="reviewQuestion">Choose a question<select id="reviewQuestion">${qs.map((x,i)=>`<option value="${i}" ${i===reviewIndex?'selected':''}>${i+1} · ${h(x.title)}</option>`).join('')}</select></label><h2 style="margin-top:24px">Question ${reviewIndex+1} of ${qs.length}</h2><blockquote>${h(q.stem)}</blockquote>${reviewMode==="vocabulary"&&!a.ready?`<label for="reviewPrediction">Predict the meaning<textarea id="reviewPrediction" rows="2">${h(a.prediction||"")}</textarea></label><label for="reviewClue">Identify a context clue<textarea id="reviewClue" rows="2">${h(a.clue||"")}</textarea></label><div class="actions"><button id="submitReviewPrediction">Submit prediction</button><button id="supportReview">Request meaning choices for support</button></div>`:""}<fieldset ${reviewMode==="vocabulary"&&!a.ready?"hidden":""} style="border:0;padding:0"><legend>Choose the best answer for this context</legend><div class="options">${q.options.map(opt=>`<label class="option"><input type="radio" name="reviewAnswer" value="${h(opt)}" ${a.value===opt?'checked':''} ${a.checked?'disabled':''}>${h(opt)}</label>`).join('')}</div></fieldset><div class="actions"><button id="checkReview" class="primary" ${a.checked||(reviewMode==="vocabulary"&&!a.ready)?'disabled':''}>Check answer</button><button id="hintReview">Optional hint</button><button id="retryReview">Try again</button><button id="resetReview">Reset this question</button></div><p id="reviewStatus" role="status"></p>${a.hintOpen?`<p class="notice">${h(q.hint)}</p>`:''}${a.checked?`<div class="feedback ${a.correct?'':'error'}" role="status"><strong>${a.correct?'Correct for this question.':'Compare the answer and explanation.'}</strong><p>${h(q.explanation)}</p><p>Apply the language in your own writing. First-attempt accuracy stays unchanged when you retry.</p></div>`:''}<div class="actions"><button id="previousReview" ${reviewIndex===0?'disabled':''}>Previous question</button><button id="nextReview" ${reviewIndex===qs.length-1?'disabled':''}>Next question</button><a href="#tasks?unit=${vocabUnit().id}">Use it in a writing task</a></div></section>`;}
function bindReview(){const q=reviewBank()[reviewIndex],get=()=>state.answers[q.id]||(state.answers[q.id]={value:''});on('reviewPrediction','input',e=>{get().prediction=e.target.value;persist();});on('reviewClue','input',e=>{get().clue=e.target.value;persist();});on('submitReviewPrediction','click',()=>{if(!get().prediction?.trim()||!get().clue?.trim()){$('reviewStatus').textContent='Add a prediction and a clue before opening the meaning choices.';return;}get().ready=true;render(false);});on('supportReview','click',()=>{get().ready=true;render(false);});on('reviewMode','change',e=>{reviewMode=e.target.value;reviewIndex=0;render(false);});on('reviewUnit','change',e=>{state.settings.unit=e.target.value;reviewIndex=0;render(false);});on('reviewQuestion','change',e=>{reviewIndex=Number(e.target.value);render(false);});document.querySelectorAll('input[name="reviewAnswer"]').forEach(el=>el.addEventListener('change',()=>{get().value=el.value;persist();}));on('checkReview','click',()=>{const a=get();if(a.checked)return;if(!a.value){$('reviewStatus').textContent='Choose an answer before checking.';return;}a.correct=a.value===q.answer;if(!a.attempted)a.firstCorrect=a.correct;a.attempted=true;a.checked=true;render(false);});on('hintReview','click',()=>{get().hintOpen=true;render(false);});on('retryReview','click',()=>{get().checked=false;get().value='';render(false);});on('resetReview','click',()=>confirmClear('Clear this question’s answer and first-attempt record? Other questions and drafts stay saved.',()=>{delete state.answers[q.id];render(false);}));on('previousReview','click',()=>{reviewIndex--;render(false);});on('nextReview','click',()=>{reviewIndex++;render(false);});}
function fullLanguageReference(){return `<section class="panel"><h2>Full language tools</h2><p>Choose words for meaning, grammar and audience. More linkers do not demonstrate better reasoning. These are language examples, not verified research evidence. Check factual claims before using them.</p>${Object.entries(D.referenceLinkers).map(([key,items])=>`<details><summary>${h(key[0].toUpperCase()+key.slice(1))} · ${items.length} expressions</summary><div class="table-wrap"><table><thead><tr><th>Expression / structure</th><th>Function</th><th>Example</th></tr></thead><tbody>${items.map(x=>`<tr><td>${h(x.w)}</td><td>${h(x.f||'Reference to an idea or noun')}</td><td>${h(x.e)}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}<p class="help">Since can express time or cause; check the context. Reference words need a clear antecedent. “Evidence suggests” requires actual evidence. A complex sentence helps only when its meaning is clear.</p><a href="#review">Practise language and genre quizzes</a></section>`;}

function planPage(){const g=currentGenre(),p=plan();return intro('01 · PLAN',isArgument()?'Take a position.<br>Give it direction.':isBio()?'Choose a person.<br>Find the central focus.':'Choose your purpose.<br>Develop your message.',g.purpose)+`<section class="panel"><label for="promptSelect">Choose your exact task<select id="promptSelect">${g.prompts.map(t=>`<option value="${t.id}" ${t.id===currentPrompt().id?'selected':''}>${h(t.text)}</option>`).join('')}</select></label><p class="notice">${h(currentPrompt().text)}</p><div class="input-grid"><div><h3>Purpose & audience</h3><p>${h(g.purpose)}</p><p class="help">${isArgument()?'You may agree, disagree or partly agree. Develop reasons and examples without inventing evidence.':isBio()?'Use verified information about real people. The practice model uses a fictional person.':'Use the selected genre’s purpose, audience, register and structure. Explain your examples rather than merely listing them.'}</p></div><div><label for="planFocus">${h(g.focusLabel)}<textarea id="planFocus" rows="3" placeholder="What is the main idea you want your reader to understand?">${h(p.focus)}</textarea></label></div></div>${scaffold()}</section><section class="panel"><h2>Plan one developed paragraph</h2><div class="input-grid">${[['point','Point / topic sentence','What does this paragraph contribute?'],['example','Relevant example / achievement','Which specific, relevant event or scenario supports the point?'],['analysis','Explanation & analysis','How does the example demonstrate the point? Why does it matter?'],['link','Link to the central focus','What connection should the reader understand?']].map(([k,label,ph])=>`<label for="plan-${k}">${label}<textarea id="plan-${k}" data-plan="${k}" rows="3" placeholder="${ph}">${h(p[k])}</textarea></label>`).join('')}</div><div class="actions"><a class="primary-link" href="#vocabulary">Next · Vocabulary in context</a><a class="secondary-link" href="#develop">Develop this paragraph</a></div></section>`;}
function vocabUnit(){return D.units.find(u=>String(u.id)===String(state.settings.unit))||D.units.find(u=>String(u.id)==='u2')||D.units[0];}
function vocabPage(){const u=vocabUnit();selectedWord=Math.min(selectedWord,u.vocab.length-1);const v=u.vocab[selectedWord],key=group()+'-'+v.id;const a=state.vocabulary[key]||{};const options=[v.d,...u.vocab.filter(x=>x.d!==v.d).slice((selectedWord+1)%8,(selectedWord+1)%8+3).map(x=>x.d)];while(options.length<4)options.push(u.vocab.find(x=>!options.includes(x.d)).d);options.sort((a,b)=>a.localeCompare(b));return intro('02 · VOCABULARY LAB','Notice the clues.<br>Discover the meaning.','Read a context, make a prediction and explain the clues before opening the definition.')+`<label for="unitSelect">Vocabulary bank<select id="unitSelect">${D.units.map(x=>`<option value="${h(x.id)}" ${x.id===u.id?'selected':''}>${h(x.num+' · '+x.name)}${['u1','u2'].includes(x.id)?' · Focus bank':' · Extended reference'}</option>`).join('')}</select></label><section class="panel" style="margin-top:20px"><div class="task-top"><span class="badge">${h(u.num)} · Context ${selectedWord+1} of ${u.vocab.length}</span><div class="actions" style="margin:0"><button id="prevWord" ${selectedWord===0?'disabled':''}>Previous word</button><button id="shuffleWord">Shuffle context card</button><button id="nextWord" ${selectedWord===u.vocab.length-1?'disabled':''}>Next word</button></div></div><h2 style="margin-top:22px">${h(v.w)}</h2><blockquote class="context-quote">${h(v.transfer)}</blockquote><label for="vocabPrediction">What do you think the word means?<textarea id="vocabPrediction" rows="2">${h(a.prediction||'')}</textarea></label><label for="vocabClue" style="margin-top:15px">Which words or details helped you?<textarea id="vocabClue" rows="2" placeholder="Quote or describe a clue from the context.">${h(a.clue||'')}</textarea></label><div class="actions"><button class="primary" id="revealVocab">Submit prediction & explain</button><button id="vocabHint">Give me a hint</button><button id="supportVocab">I need the definition for support</button><button id="resetVocab">Reset this word</button></div><p id="vocabHintText" class="help" hidden>${h(v.clue)}</p><p id="vocabValidation" role="status"></p>${a.revealed?`<div class="feedback"><h3>Meaning & context clues</h3><p><strong>${h(v.w)}</strong>: ${h(v.d)}</p><p><strong>Context to compare:</strong> “${h(v.transfer)}”</p><p><strong>Relevant clue:</strong> “${h(v.evidence)}”. ${h(v.clueExplanation)} Your prediction and clue are self-reviewed, not automatically marked.</p><p><strong>Your prediction:</strong> ${h(a.prediction||'Definition requested for support.')}</p><p><strong>Your clue:</strong> ${h(a.clue||'Add a clue after reading the explanation.')}</p><p><strong>Natural phrases:</strong> ${v.collocations.map(x=>`<span class="badge">${h(x)}</span>`).join(' ')}</p></div><h3>Transfer to a new context</h3><blockquote class="context-quote">${h(v.e)}</blockquote><fieldset style="border:0;padding:0"><legend>Which meaning fits this new context?</legend><div class="options">${options.map((opt,i)=>`<label class="option"><input type="radio" name="vocabTransfer" value="${h(opt)}" ${a.transfer===opt?'checked':''} ${a.transferChecked?'disabled':''}>${h(opt)}</label>`).join('')}</div></fieldset><div class="actions"><button id="checkTransfer" class="primary" ${a.transferChecked?'disabled':''}>Check transfer</button><button id="retryTransfer">Try transfer again</button></div>${a.transferChecked?`<div class="feedback ${a.transferCorrect?'':'error'}" role="status"><strong>${a.transferCorrect?'Correct meaning in this context.':'Not quite in this context.'}</strong><p>${h(v.d)} Compare the context “${h(v.e)}” with this meaning. The grammar may change when a word has more than one part of speech.</p></div>`:''}<label for="vocabOwn" style="margin-top:18px">Use the word naturally in your own sentence or paragraph<textarea id="vocabOwn" rows="3">${h(a.own||'')}</textarea></label><p class="help">Self-review: Does your sentence express the intended meaning? Does the phrase fit your genre and audience? This original writing is not automatically scored.</p>`:''}</section><section class="panel"><h2>Vocabulary bank & context cards</h2><p>Choose a word to return to its context card. Definitions remain hidden until you request this reference support.</p><div class="pill-row">${u.vocab.map((word,i)=>`<button data-word="${i}">${h(word.w)}</button>`).join('')}</div><button id="definitionList">Request definition list for support</button><div id="definitionTable" hidden><div class="table-wrap"><table><thead><tr><th>Word</th><th>Meaning</th><th>Example</th><th>Natural phrases</th></tr></thead><tbody>${u.vocab.map(word=>`<tr><td>${h(word.w)}</td><td>${h(word.d)}</td><td>${h(word.e)}</td><td>${h(word.collocations.join('; '))}</td></tr>`).join('')}</tbody></table></div></div></section>${phraseLab()}<div class="actions"><a class="primary-link" href="#practice">Next · Practice checkpoints</a></div>`;}
function phraseLab(){const list=D.comparisons.filter(c=>state.settings.genre==='essay'?['impact','awareness','commitment','community','dedication','charity'].includes(c.id):['resilient','legacy','recognition','pioneer','perseverance','innovation'].includes(c.id));return `<section class="panel"><h2>Natural phrasing lab</h2><p class="muted">Distinguish grammar errors, awkward combinations and alternatives with different meanings.</p>${list.map((c,i)=>{const a=state.comparisons[group()+'-'+c.id];return `<details><summary>${h(c.word)} · Choose and explain</summary><p>Which phrase suits the intended ${c.id==='recognition'?'meaning of public praise':'meaning'}?</p><div class="actions"><button data-phrase="${c.id}" data-natural="0" ${a?'disabled':''}>${h(c.awkward)}</button><button data-phrase="${c.id}" data-natural="1" ${a?'disabled':''}>${h(c.natural)}</button></div>${a?`<div class="feedback ${a.correct?'':'error'}"><strong>${a.correct?'Suitable choice.':'Compare the preferred phrase.'}</strong><p>${h(c.kind)}: ${h(c.why)}</p><p>Natural alternative: <strong>${h(c.alternative)}</strong></p></div><button data-reset-phrase="${c.id}">Reset comparison</button>`:''}</details>`;}).join('')}</section>`;}
function practicePage(){if(!isFocusRoute())return reviewPage();const qs=bank();selectedQuestion=Math.max(0,Math.min(selectedQuestion,qs.length-1));const q=qs[selectedQuestion],a=state.answers[q.id]||{value:'',chunks:[]};const score=qs.filter(q=>state.answers[q.id]?.firstCorrect).length,done=qs.filter(q=>state.answers[q.id]?.attempted).length;let input='';
 if(q.options)input=`<fieldset style="border:0;padding:0"><legend class="sr-only">Choose one answer</legend><div class="options">${q.options.map(o=>`<label class="option"><input type="radio" name="practiceAnswer" value="${h(o)}" ${a.value===o?'checked':''} ${a.checked?'disabled':''}>${h(o)}</label>`).join('')}</div></fieldset>`;
 else if(q.kind==='order'){const chunks=q.answers[0].split(' '),used=a.chunks||[];input=`<p class="help">Select chunks in order. Every chunk is a button: use Tab and Enter, or type a complete alternative below.</p><div class="word-bank">${chunks.map((w,i)=>({w,i})).reverse().map(({w,i})=>`<button data-chunk="${i}" ${used.includes(i)||a.checked?'disabled':''}>${h(w)}</button>`).join('')}</div><p class="sentence-output" aria-label="Built sentence">${h(used.map(i=>chunks[i]).join(' ')||'Your sentence will appear here.')}</p><div class="actions"><button id="undoChunk">Undo last chunk</button><button id="clearChunks">Clear sentence</button></div><label for="practiceText">Or type the complete sentence<input id="practiceText" value="${h(a.typed||'')}" ${a.checked?'disabled':''}></label>`;}
 else input=`<label for="practiceText">Your answer<input id="practiceText" value="${h(a.value)}" autocomplete="off" ${a.checked?'disabled':''}></label>`;
 return intro('03 · PRACTICE CHECKPOINTS','Make each choice<br>serve the meaning.','Practise language in the topic context. These scores describe closed-answer practice, not your writing ability.')+`<section class="panel"><div class="task-top"><span class="badge">${h(state.settings.pathway)} · ${h(currentGenre().name)}</span><span class="score-box">First-attempt accuracy: ${score}/${done||0} attempted · ${qs.length} questions</span></div><label for="questionSelect" style="margin-top:20px">Choose a checkpoint<select id="questionSelect">${qs.map((x,i)=>`<option value="${i}" ${i===selectedQuestion?'selected':''}>${i+1}. ${h(x.title)}</option>`).join('')}</select></label><h2 style="margin-top:25px">${h(q.title)}</h2><p class="context-quote">${h(q.stem)}</p>${input}<div class="actions"><button id="checkAnswer" class="primary" ${a.checked?'disabled':''}>Check</button><button id="tryAgain">Try again</button><button id="clearAnswer">Clear answer</button><button id="resetActivity">Reset activity</button><button id="showHint">Hint</button></div><p id="practiceHint" class="notice" hidden>${h(q.hint)}</p><p id="practiceValidation" role="status"></p>${a.checked?`<div class="feedback ${a.correct?'':'error'}" role="status"><h3>${a.correct?'Correct for this item.':'Not quite — compare and retry.'}</h3><p>Accepted answer${q.answers.length>1?'s':''}: <strong>${h(q.answers.join(' / '))}</strong></p><p>${h(q.explanation)}</p><p class="help">${h(q.hint)} A retry helps you learn; it does not change your first-attempt result.</p></div>`:''}<div class="actions"><button id="prevQuestion" ${selectedQuestion===0?'disabled':''}>Previous checkpoint</button><button id="nextQuestion" ${selectedQuestion===qs.length-1?'disabled':''}>Next checkpoint</button><a class="secondary-link" href="#develop">Develop your own paragraph</a></div></section>`;}
function developPage(){const key=group(),a=state.development[key]||{},model=currentGenre().model;return intro('04 · DEVELOP',isArgument()?'Turn a reason<br>into an argument.':isBio()?'Turn an achievement<br>into a meaningful account.':'Develop an example.<br>Explain its significance.','Notice what the example demonstrates. Explain the connection rather than leaving your reader to infer it.')+`<div class="grid"><section class="panel warm"><span class="badge">Underdeveloped practice example</span><p class="model" style="margin-top:16px">${h(model.weak)}</p><p class="help">Which claims need explanation or specific support?</p></section><section class="panel soft"><span class="badge">Developed model · original teaching text</span><p class="model" style="margin-top:16px">${h(model.strong)}</p><p class="help">${state.settings.genre==='biography'?'Maya is fictional. The timeline distinguishes completed preparation from an ongoing earlier period.':'The project is hypothetical. No invented research result is presented as fact.'}</p></section></div><section class="panel" style="margin-top:20px"><h2>Notice the development</h2><ol class="annotated"><li><strong>Point:</strong> Identify the claim or admirable quality.</li><li><strong>Explanation:</strong> Find the reason the point matters.</li><li><strong>Example:</strong> Identify a specific action or scenario.</li><li><strong>Analysis:</strong> Explain what the action demonstrates.</li><li><strong>Link:</strong> Connect the interpretation to the thesis or central focus.</li></ol><p class="notice">${state.settings.pathway==='challenge'?'Challenge: identify a reasonable limitation or alternative interpretation. In an essay, evaluate a counterargument; in a biography, consider how much one event can show about character.':state.settings.pathway==='core'?'Core: remove the model and develop a different example that supports the same focus.':'Foundation: identify the five functions in the model, then change the example and explain the new connection.'}</p>${[['explanation','Complete the missing explanation',isFocusRoute()?(isArgument()?'A reading mentor can develop patience because …':'Maya’s response to the setback demonstrates perseverance because …'):'My example supports the main idea because …'],['link','Complete the missing link',isFocusRoute()?(isArgument()?'This example strengthens the case for student choice because …':'This achievement helps explain why Maya is admirable because …'):'This example connects to my central focus because …'],['paragraph','Write an original developed paragraph','Use your own point, explanation, specific example, analysis and link. These functions may share sentences.']].map(([k,label,ph])=>`<label for="develop-${k}" style="margin-top:16px">${label}<textarea id="develop-${k}" data-develop="${k}" placeholder="${h(ph)}" rows="${k==='paragraph'?6:3}">${h(a[k]||'')}</textarea></label>`).join('')}${scaffold()}<div class="actions"><button id="developReview" class="primary">Open targeted self-review</button><button id="clearDevelop">Reset these paragraph tasks</button><a class="secondary-link" href="#draft">Next · Your original draft</a></div><div id="developFeedback"></div></section>`;}
function draftPage(){const d=draft(),g=currentGenre();return intro('05 · DRAFT → REVIEW → REVISE','Write with purpose.<br>Revise with evidence.','Keep your meaning at the centre. Browser checks quote your text and separate observable patterns from questions for human review.')+`<section class="panel"><label for="draftPrompt">Writing task<select id="draftPrompt">${g.prompts.map(t=>`<option value="${t.id}" ${t.id===currentPrompt().id?'selected':''}>${h(t.text)}</option>`).join('')}</select></label><p class="notice">${h(currentPrompt().text)}</p><p class="help">Your focus: <strong>${h(plan().focus||'Add your thesis or central focus in Plan.')}</strong> <a href="#plan">Edit your plan</a></p>${timerHTML()}<details><summary>Genre checklist · self-review your draft</summary><p>These checks are your judgement, not automatic marks.</p>${(g.checklist||["Develop specific achievements and their significance","Connect examples to the central focus","Check facts, grammar and register"]).map((item,i)=>`<label class="check-row"><input type="checkbox" data-genre-check="${i}" ${plan()["check-"+i]==="yes"?"checked":""}>${h(item)}</label>`).join("")}</details><label class="check-row"><input id="independent" type="checkbox" ${d.independent?'checked':''}>Independent mode · hide frames and models</label><div id="draftSupport" ${d.independent?'hidden':''}>${scaffold()}<details><summary>See the genre model for comparison</summary><p class="model">${h(g.model.strong)}</p><p class="help">Use the model to understand development, then write original content.</p></details></div><label for="draftText">Your original ${h(g.name.toLowerCase())}<textarea id="draftText" class="draft-box" placeholder="Develop your own ideas here. Use paragraph breaks to organise them.">${h(d.text)}</textarea></label><div class="draft-meta"><span id="wordCount">${E.countWords(d.text)} words · Suggested target ${h(currentGenre().wordRange||D.config.wordMin+'–'+D.config.wordMax+' words')}</span><span>All pathways share this saved draft · task-specific</span></div><div class="actions"><button id="analyse" class="primary">Review my text / save revision</button><button id="copyDraft">Copy writing</button><button id="downloadDraft">Download writing</button><button id="clearDraft">Clear this draft</button></div><p class="help" id="copyStatus" role="status"></p><div class="notice warning"><strong>Browser checks, not comprehensive writing assessment.</strong> No AI/backend service is connected. The checks can flag a few patterns and quote passages; they cannot certify reasoning, relevance, facts, grammar overall or a writing grade. Your teacher/peer and targeted self-review address those criteria.</div></section><section class="panel" id="writingFeedback">${d.feedback?feedbackHTML(d.feedback):'<p class="muted">Your observations and two or three revision priorities will appear here after you request a review.</p>'}</section>${versionsHTML(d)}`;}
function timerHTML(){const t=state.timer;return `<div class="timer" aria-label="Writing timer"><label for="timerMinutes">Minutes<input id="timerMinutes" type="number" min="1" max="120" value="${t.minutes}"></label><output id="timerDisplay" aria-label="Time remaining">${formatTime(remaining())}</output><button id="timerStart">${t.running?'Pause':t.remaining<=0?'Start again':'Start / resume'}</button><button id="timerReset">Reset timer</button><label class="check-row"><input id="untimed" type="checkbox" ${t.untimed?'checked':''}>Untimed</label><span class="small muted" id="timerStatus">${t.untimed?'Untimed mode':t.running?'Running':'Paused / ready'}</span></div>`;}
function feedbackHTML(a){let out=`<h2>Review the evidence in your text</h2><span class="badge">No overall score · ${h(currentGenre().standards)}</span>`;if(a.insufficient.length)out+=`<div class="notice warning">${a.insufficient.map(s=>`<p>${h(s)}</p>`).join('')}</div>`;
 if(a.observations.length)out+=`<details open><summary>Observable features · not a quality verdict</summary>${a.observations.map(o=>`<h3>${h(o.title)}</h3><blockquote class="context-quote" style="font-size:17px">${h(o.quote)}</blockquote><p>${h(o.detail)}</p>`).join('')}</details>`;
 if(a.priorities.length)out+=`<h3>Suggested edits · ${a.priorities.length} priority pattern${a.priorities.length>1?'s':''}</h3><div class="review-list">${a.priorities.map(p=>`<article class="review-item"><span class="badge">${h(p.criterion)}</span><h3 style="margin-top:10px">${h(p.title)}</h3><blockquote class="context-quote" style="font-size:17px">${h(p.quote)}</blockquote><p>${h(p.explanation)}</p><p>${h(p.action)}</p>${p.revision?`<p class="revision"><strong>Possible revision, subject to your meaning:</strong> “${h(p.revision)}”</p>`:''}</article>`).join('')}</div>`;
 if(!a.priorities.length&&a.wordCount)out+='<p class="notice">No issue from the small browser pattern list was detected. This does not mean the passage is error-free or well developed.</p>';
 if(a.checks.length)out+='<h3 style="margin-top:25px">Three questions for targeted self-review</h3>'+a.checks.map(c=>`<article class="review-item"><span class="badge">${h(c.criterion)}</span><h3 style="margin-top:10px">${h(c.title)}</h3><blockquote class="context-quote" style="font-size:17px">${h(c.quote)}</blockquote><p>${h(c.question)}</p><label for="review-${c.id}">My evidence and next revision<textarea id="review-${c.id}" data-review="${c.id}" rows="3">${h(draft().review[c.id]||'')}</textarea></label></article>`).join('')+'<p class="help">Revise the original text above, then request another review. Teacher/peer judgement is still needed for the open criteria.</p>';
 return out;
}
function versionsHTML(d){if(!d.versions.length)return '';const last=d.versions.at(-1),prev=d.versions.at(-2),cmp=prev?E.compareVersions(prev,last):null;return `<section class="panel"><h2>Your revision history</h2><p class="help">Up to eight distinct submitted versions are kept per task. Rechecking unchanged writing does not add a version or award points.</p>${cmp?`<div class="notice"><strong>${cmp.changed?'Text changed':'Text unchanged'} · word difference ${cmp.wordChange>=0?'+':''}${cmp.wordChange}</strong><p>Previously flagged patterns no longer detected: ${h(cmp.removed.join('; ')||'None yet.')}</p><p>Patterns still/newly detected: ${h(cmp.remaining.join('; ')||'None from the limited list.')}</p><p>${h(cmp.note)}</p></div>`:''}${d.versions.map((v,i)=>`<details class="version"><summary>Version ${i+1} · ${new Date(v.date).toLocaleString()} · ${E.countWords(v.text)} words</summary><pre>${h(v.text)}</pre><button data-copy-version="${i}">Copy this version</button></details>`).reverse().join('')}</section>`;}
function progressPage(){const qs=bank(),done=qs.filter(q=>state.answers[q.id]?.attempted),correct=done.filter(q=>state.answers[q.id]?.firstCorrect),r=state.reflections[group()]||{};return intro('06 · REFLECT','See your practice.<br>Choose your next step.','Completion, first-attempt accuracy and writing revision are different kinds of evidence. Practice XP awards 5 points per attempted closed question plus 5 for a correct first attempt; retries add no points. Levels mark every 100 points. None is an overall writing grade.')+`<section class="panel"><h2>${h(currentGenre().name)} · ${h(state.settings.pathway)}</h2><p>${done.length}/${qs.length} closed checkpoints attempted · ${correct.length}/${done.length} correct on first attempt</p><div class="progress-bar" role="progressbar" aria-label="Checkpoints attempted" aria-valuenow="${done.length}" aria-valuemin="0" aria-valuemax="${qs.length}"><span style="width:${done.length/qs.length*100}%"></span></div>${[...new Set(qs.map(q=>q.kind))].map(kind=>{const questions=qs.filter(q=>q.kind===kind),attempted=questions.filter(q=>state.answers[q.id]?.attempted);return `<div class="progress-row"><a href="#practice?question=${qs.findIndex(q=>q.kind===kind)}">${h(questions[0]?.title||kind)}</a><span>${attempted.filter(q=>state.answers[q.id]?.firstCorrect).length}/${attempted.length} first-attempt correct · ${questions.length} available</span></div>`;}).join('')}<p class="help" style="margin-top:16px">Focus checkpoint scores are separate for each genre and pathway. Review quizzes keep records by quiz mode and vocabulary unit. Retrying is encouraged; no score locks a route. Activity reset clears that activity’s recorded attempt only.</p></section><section class="panel"><h2>One strength. One next step.</h2>${[['strength','A strength, with evidence from my writing'],['next','An area for improvement'],['action','The practical revision I will make']].map(([k,l])=>`<label style="margin-top:15px" for="reflect-${k}">${l}<textarea data-reflect="${k}" id="reflect-${k}" rows="2">${h(r[k]||'')}</textarea></label>`).join('')}<div class="actions"><button id="participation">Create a practice participation record</button></div><p class="help">This records practice and reflection; it is not an achievement grade or proof that you completed the whole programme.</p><div id="participationRecord"></div></section><section class="panel"><h2>Protect your work</h2><p>Local saves remain in this browser on this device. They do not sync automatically. Back up before clearing browser data or changing devices.</p><div class="actions"><button id="exportAll" class="primary">Download work backup</button><button id="exportReport">Download progress summary</button><button id="clearAll" class="danger">Reset all studio work</button></div><label for="importBackup" style="margin-top:20px">Restore a studio backup<input id="importBackup" type="file" accept="application/json,.json"></label><p class="help">Valid records merge with current work; the newer draft wins. The imported settings become active. Invalid files are rejected.</p><p id="importStatus" role="status"></p>${recoveryRaw?'<button id="recoveryBackup">Download untouched recovery data</button>':''}</section>`;}
function referencePage(){return intro('REFERENCE LIBRARY','Keep useful language<br>within reach.','The original extended unit vocabulary and all writing formats are retained. All covered units have working writing tasks and saved drafts. Biography and volunteering have the supplied standards mappings; other genres use labelled self-review criteria.')+`<section class="panel"><h2>Extended vocabulary banks</h2><div class="ref-list">${D.units.map(u=>`<a href="#vocabulary?unit=${encodeURIComponent(u.id)}">${h(u.num+' · '+u.name)}<br><small>${u.vocab.length} context entries</small></a>`).join('')}</div></section><section class="panel"><h2>Linkers: meaning before quantity</h2><div class="table-wrap"><table><thead><tr><th>Relationship</th><th>Pattern</th><th>Example</th></tr></thead><tbody>${[
 ['Reason','because + clause / because of + noun phrase','Students returned because the role was meaningful.'],['Contrast','although + clause / despite + noun phrase','Although the task was difficult, she continued.'],['Result','therefore / as a result','The pupils needed more support. As a result, she revised the activity.'],['Example','for example / for instance','A suitable role can teach patience. For example, mentors may explain words repeatedly.'],['Addition','in addition / furthermore','The project supports families. In addition, it offers practical experience.'],['Reference','this approach / these achievements / they','These achievements demonstrate perseverance.'],['Time','before / by the time / after','Before the club opened, she had collected books.']
 ].map(row=>`<tr>${row.map(x=>`<td>${h(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="help">Use a linker only when it expresses the intended relationship. There is no compulsory number of linkers. Starting with And, But or So is not automatically a grammar error; choose a style suited to the task.</p></section><section class="panel"><h2>Biography tense timeline</h2><ol><li><strong>Earlier completed action:</strong> she had collected the books.</li><li><strong>Earlier ongoing duration:</strong> she had been preparing for two months.</li><li><strong>Later past event:</strong> the club opened.</li></ol><p>Use past perfect when it clarifies an earlier event. Before or after may already show the order, so simple past can sometimes be acceptable. Do not add past perfect mechanically.</p></section><section class="panel"><h2>Retained genre guides · supplementary</h2><p class="help">These do not extend the supplied UO 1.g / UO 2.h alignment to every genre. Audience and task instructions take priority.</p>${D.legacyTasks.map(t=>`<details><summary>${h(t.type)} · ${h(t.unit)}</summary><p>Original suggested range: ${h(t.len)}. Confirm with your teacher.</p><h3>Practice prompts</h3><ul>${t.prompts.map(p=>`<li>${h(p)}</li>`).join('')}</ul><h3>Possible structure</h3><ul>${t.structure.map(p=>`<li>${h(p)}</li>`).join('')}</ul><p class="help">Use the structure flexibly. Develop reasons and examples; do not invent statistics, force stock phrases or treat a relative clause as proof of good writing.</p></details>`).join('')}</section>${fullLanguageReference()}`;}
function teacherPage(){const total=['essay','biography'].reduce((n,g)=>n+['foundation','core','challenge'].reduce((s,p)=>s+E.makeBank(g,p).length,0),0);return intro('TEACHER GUIDANCE','Purposeful practice.<br>Honest assessment.','The uploaded school standards govern the two primary genres. Supplementary writing guidance does not impose C1 exam structures or word limits.')+`<section class="panel"><h2>Settings & assessment boundaries</h2><p>Default suggested target: ${h(currentGenre().wordRange||D.config.wordMin+'–'+D.config.wordMax+' words')}. Timer: ${D.config.minutes} minutes, adjustable or untimed. These are editable defaults because the supplied prompt does not specify a compulsory word count or duration.</p><p>The two standards-mapped focus genres × three pathways × 15 closed questions = ${total} curated closed checkpoints, plus three open development tasks per route (${3*6} open tasks). There are ${D.units.reduce((n,u)=>n+u.vocab.length,0)} vocabulary entries across ${D.units.length} banks, including ${D.comparisons.length} phrase comparisons split between the two primary genres. Role-model vocabulary also remains in its original Unit 3 bank.</p><p>No backend or external writing analysis service is connected. The static checks are deliberately limited. A validated semantic service would need a server-side endpoint, secret management, privacy controls and teacher calibration before claims about reasoning or writing quality.</p><p>Original open writing, self-review and teacher/peer feedback are the learning evidence. Closed-answer practice scores do not become rubric marks.</p></section><section class="panel"><h2>Standards → learning evidence</h2><div class="table-wrap"><table><thead><tr><th>Standard</th><th>Student success criterion</th><th>Activity / evidence</th></tr></thead><tbody>${[
 ['UO 1.g.a / UO 2.h.a','I can plan a clear purpose and develop ideas with relevant support.','Purpose, focus and paragraph plan; development models; original draft.'],['UO 1.g.b / UO 2.h.b','I can organise ideas and use links and reference words purposefully.','Contextual linkers, sentence order, paragraph links and self-review.'],['UO 1.g.c / UO 2.h.c','I can maintain an appropriate formal style.','Genre guidance, cautious phrase comparisons, register review of quoted text.'],['UO 1.g.d / UO 2.h.d','I can use topic vocabulary and complex structures accurately.','Context inference, collocations, original word use, agreement and verb tasks.'],['UO 1.g.e / UO 2.h.e','I can explain a strength, identify an improvement and make a practical revision.','Quoted-text review, version comparison and reflection.'],['LO 1.5.a.a','I can describe what an admirable person did, how and with specific examples.','Biography achievement planning, interpretation and original article.'],['LO 1.5.a.b','I can choose past perfect simple and continuous appropriately.','Timeline, verb-form correction and teacher review of the biography.']
 ].map(row=>`<tr>${row.map(x=>`<td>${h(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="notice">UO 2.h includes essay and webpage writing. Both now have drafting tasks. The webpage text practice cannot verify a built website’s navigation or usability; teacher review of the finished webpage is still required.</p></section><section class="panel"><h2>Retained standard wording</h2><details><summary>UO 1.g · Biographical articles</summary><p>Learners can write a biography or a profile of a role model.</p>${standardsText('human achievements')}</details><details><summary>LO 1.5.a · Admirable person and achievements</summary><p>Learners will be able to describe an admirable person and talk about his/her past achievements.</p><ol type="a"><li>Describe the person and his/her achievements, including what the person did, how it was done and what happened along the way, and provide examples.</li><li>Use past perfect simple and past perfect continuous properly.</li></ol></details><details><summary>UO 2.h · Volunteering essay and webpage</summary><p>Learners can write an essay and a webpage about volunteering.</p>${standardsText('volunteering')}</details></section><section class="panel"><h2>Classroom use</h2><ol><li>Select the genre and allow a suitable pathway. Change pathways without losing drafts.</li><li>Have students predict vocabulary meanings before opening definitions.</li><li>Use practice accuracy to guide support, then require an original paragraph and draft.</li><li>Ask learners to explain their quoted evidence during self/peer review.</li><li>Review the actual text against your assessment rubric. Do not convert browser observations into marks.</li></ol><p>Source: supplied “Pasted text.txt” standards; British Council “An opinion essay” worksheet (2019) for clear positions, justified reasons and cautious claims. The models and activities here are original; the source essay is not copied.</p><p class="help">Privacy: no names are required and no writing is sent to a server. Backups contain student writing; handle them appropriately. The old site held drafts and XP only in memory, so unsaved old-session work cannot be recovered after a reload.</p></section>`;}
function standardsText(topic){return `<ol type="a"><li>Plan ideas and support with clear purposes, for example informational or argumentative, about ${topic==='volunteering'?'volunteering':'the topic of human achievements'}.</li><li>Arrange ideas logically with a clear outline and proper use of linking devices and reference words.</li><li>Use appropriate formal writing styles consistently.</li><li>Use a wide range of topic-based vocabulary and complex grammatical structures.</li><li>Provide detailed explanation of the strong points and areas for improvement of the products and suggest practical solutions for future improvement.</li></ol>`;}
function route(){const [page,query]=location.hash.slice(1).split('?'),params=new URLSearchParams(query||'');if(location.hash!==lastRouteHash){lastRouteHash=location.hash;if(page==='tasks')selectedTaskUnit=params.get('unit')||'all';if(params.has('unit')&&D.units.some(u=>u.id===params.get('unit'))){state.settings.unit=params.get('unit');selectedWord=0;}if(params.has('task')){const found=Object.entries(D.genres).find(([k,g])=>g.prompts.some(p=>p.id===params.get('task')));if(found){state.settings.genre=found[0];state.settings.prompt=params.get('task');}}if(params.has('question')){selectedQuestion=Number(params.get('question'))||0;reviewIndex=selectedQuestion;}}return pages.includes(page)?page:'home';}
function render(focus=true){const page=route();const xp=Object.values(state.answers).reduce((n,a)=>n+(a.attempted?(a.firstCorrect?10:5):0),0);$('practiceXP').textContent='Practice XP '+xp+' · Level '+(1+Math.floor(xp/100));$('practiceXP').title='Participation points: 5 per attempted closed question, plus 5 for a correct first attempt. Retries add no points. Not a writing grade.';state.visited[group()+'-'+page]=true;$('genre').innerHTML=Object.entries(D.genres).map(([key,g])=>`<option value="${h(key)}">${h(g.unit.split(' · ')[0].split(' — ')[0]+' · '+g.name)}</option>`).join('');$('genre').value=state.settings.genre;$('pathway').value=state.settings.pathway;document.querySelectorAll('#nav a').forEach(a=>{if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const renderer={tasks:tasksPage,review:reviewPage,home,plan:planPage,vocabulary:vocabPage,practice:practicePage,develop:developPage,draft:draftPage,progress:progressPage,reference:referencePage,teacher:teacherPage};$('main').innerHTML=(recoveryMessage?`<div class="notice warning">${h(recoveryMessage)} <a href="#progress">Backup & recovery</a></div>`:'')+renderer[page]();bindPage(page);persist();if(focus){$('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'});}}
function on(id,event,handler){if($(id))$(id).addEventListener(event,handler);}
function bindPage(page){
 on('promptSelect','change',e=>{state.settings.prompt=e.target.value;history.replaceState(null,'','#'+location.hash.slice(1).split('?')[0]+'?task='+encodeURIComponent(e.target.value)+'&unit='+currentGenre().unitId);lastRouteHash=location.hash;render(false);});on('draftPrompt','change',e=>{state.settings.prompt=e.target.value;history.replaceState(null,'','#'+location.hash.slice(1).split('?')[0]+'?task='+encodeURIComponent(e.target.value)+'&unit='+currentGenre().unitId);lastRouteHash=location.hash;render(false);});
 on('planFocus','input',e=>{plan().focus=e.target.value;persist();});document.querySelectorAll('[data-plan]').forEach(el=>el.addEventListener('input',e=>{plan()[e.target.dataset.plan]=e.target.value;persist();}));
 document.querySelectorAll('[data-genre-check]').forEach(el=>el.addEventListener('change',()=>{plan()['check-'+el.dataset.genreCheck]=el.checked?'yes':'';persist();}));if(page==='vocabulary')bindVocab();if(page==='practice'){if(isFocusRoute())bindPractice();else bindReview();}if(page==='review')bindReview();if(page==='tasks')bindTasks();
 document.querySelectorAll('[data-develop]').forEach(el=>el.addEventListener('input',e=>{const a=state.development[group()]||(state.development[group()]={});a[e.target.dataset.develop]=e.target.value;persist();}));
 on('developReview','click',()=>{const text=state.development[group()]?.paragraph||'';const a=E.analyseWriting(text,state.settings.genre,plan().focus,currentPrompt().text);$('developFeedback').innerHTML=feedbackHTML(a);document.querySelectorAll('#developFeedback [data-review]').forEach(el=>el.addEventListener('input',e=>{draft().review[e.target.dataset.review]=e.target.value;persist();}));announce(text?'Three passages and self-review prompts are ready. These are not quality grades.':'Write your paragraph before review.');});
 on('clearDevelop','click',()=>confirmClear('Clear the three open paragraph tasks for this genre and pathway? Your full draft is kept.',()=>{delete state.development[group()];render(false);}));
 on('draftText','input',e=>{draft().text=e.target.value;draft().updatedAt=Date.now();$('wordCount').textContent=`${E.countWords(e.target.value)} words · Suggested target ${h(currentGenre().wordRange||D.config.wordMin+'–'+D.config.wordMax+' words')}`;persist();});
 on('independent','change',e=>{draft().independent=e.target.checked;$('draftSupport').hidden=e.target.checked;persist();});
 on('analyse','click',()=>{const d=draft(),a=E.analyseWriting(d.text,state.settings.genre,plan().focus,currentPrompt().text);d.feedback=a;if(d.text.trim()&&d.versions.at(-1)?.text!==d.text){d.versions.push({text:d.text,date:Date.now(),focus:plan().focus,analysis:a});d.versions=d.versions.slice(-8);}persist();render(false);$('writingFeedback').scrollIntoView({block:'start',behavior:'auto'});announce(a.wordCount?'Review ready. Check quoted observations and targeted self-review. No overall score is assigned.':'No writing submitted. Insufficient evidence for all criteria.');});
 document.querySelectorAll('[data-review]').forEach(el=>el.addEventListener('input',e=>{draft().review[e.target.dataset.review]=e.target.value;persist();}));
 on('copyDraft','click',()=>copyText(draft().text));on('downloadDraft','click',()=>download(currentPrompt().id+'.txt',draft().text));document.querySelectorAll('[data-copy-version]').forEach(el=>el.addEventListener('click',()=>copyText(draft().versions[Number(el.dataset.copyVersion)].text)));
 on('clearDraft','click',()=>confirmClear('Clear this task’s draft, its submitted versions and its self-review? Other drafts and practice stay saved.',()=>{delete state.drafts[currentPrompt().id];render(false);}));
 bindTimer();
 document.querySelectorAll('[data-reflect]').forEach(el=>el.addEventListener('input',e=>{const a=state.reflections[group()]||(state.reflections[group()]={});a[e.target.dataset.reflect]=e.target.value;persist();}));
 on('participation','click',()=>{const qs=bank(),count=qs.filter(q=>state.answers[q.id]?.attempted).length;$('participationRecord').innerHTML=`<div class="certificate"><p class="eyebrow">PRACTICE PARTICIPATION RECORD</p><h2>Learning with purpose</h2><p>${h(currentGenre().name)} · ${h(state.settings.pathway)} pathway</p><p>${count} of ${qs.length} closed checkpoints attempted.<br>${draft().versions.length} submitted writing versions for the selected task.</p><p>${new Date().toLocaleDateString()}</p><p class="help">This is a record of practice, not a writing grade, verified mastery or full-programme completion certificate.</p></div><div class="actions no-print"><button id="printRecord">Print participation record</button></div>`;on('printRecord','click',()=>{document.body.classList.add('printing-record');window.print();document.body.classList.remove('printing-record');});announce('Practice participation record created with accurate attempt counts.');});
 on('exportAll','click',backup);on('exportReport','click',exportReport);on('clearAll','click',()=>confirmClear('Delete all studio drafts, versions, plans, answers, practice scores and reflections in this browser? Download a backup first. Other websites’ saved data will not be touched.',()=>{state=E.defaultState();storageOK=true;recoveryMessage='';selectedQuestion=0;selectedWord=0;persist();render(false);}));on('recoveryBackup','click',()=>download('stage11-recovery-untouched.json',recoveryRaw,'application/json'));on('importBackup','change',importBackup);
}
function bindVocab(){document.querySelectorAll('[data-word]').forEach(el=>el.addEventListener('click',()=>{selectedWord=Number(el.dataset.word);render(false);$('vocabPrediction').focus();}));on('definitionList','click',()=>{$('definitionTable').hidden=!$('definitionTable').hidden;$('definitionList').textContent=$('definitionTable').hidden?'Request definition list for support':'Hide definition list';});const u=vocabUnit(),v=u.vocab[selectedWord],key=group()+'-'+v.id;const get=()=>state.vocabulary[key]||(state.vocabulary[key]={});on('unitSelect','change',e=>{state.settings.unit=e.target.value;selectedWord=0;render(false);});on('shuffleWord','click',()=>{selectedWord=(selectedWord+1+Math.floor(Math.random()*(u.vocab.length-1)))%u.vocab.length;render(false);});on('prevWord','click',()=>{selectedWord--;render(false);});on('nextWord','click',()=>{selectedWord++;render(false);});on('vocabPrediction','input',e=>{get().prediction=e.target.value;persist();});on('vocabClue','input',e=>{get().clue=e.target.value;persist();});on('vocabOwn','input',e=>{get().own=e.target.value;persist();});on('vocabHint','click',()=>{$('vocabHintText').hidden=false;announce('Hint shown. Find actions or consequences around the target word.');});
 on('revealVocab','click',()=>{if(!get().prediction?.trim()||!get().clue?.trim()){$('vocabValidation').textContent='Add a prediction and a context clue first, or choose definition support.';announce($('vocabValidation').textContent);return;}get().revealed=true;render(false);announce('Definition and context explanation revealed. Compare them with your prediction.');});on('supportVocab','click',()=>{get().revealed=true;get().support=true;render(false);announce('Definition shown as requested support.');});on('resetVocab','click',()=>confirmClear('Clear your prediction, clue, transfer attempt and original sentence for this word only?',()=>{delete state.vocabulary[key];render(false);}));
 document.querySelectorAll('input[name="vocabTransfer"]').forEach(el=>el.addEventListener('change',()=>{get().transfer=el.value;persist();}));on('checkTransfer','click',()=>{const a=get();if(a.transferChecked)return;if(!a.transfer){$('vocabValidation').textContent='Choose a transfer answer first.';announce('Choose a transfer answer first.');return;}a.transferChecked=true;a.transferCorrect=a.transfer===v.d;if(a.firstCorrect===undefined)a.firstCorrect=a.transferCorrect;persist();render(false);announce(a.transferCorrect?'Correct meaning in the transfer context.':'Not quite. Compare the definition and context.');});on('retryTransfer','click',()=>{get().transferChecked=false;get().transfer='';render(false);});
 document.querySelectorAll('[data-phrase]').forEach(el=>el.addEventListener('click',()=>{const k=group()+'-'+el.dataset.phrase;if(state.comparisons[k])return;state.comparisons[k]={correct:el.dataset.natural==='1'};render(false);announce('Phrase explanation shown.');}));document.querySelectorAll('[data-reset-phrase]').forEach(el=>el.addEventListener('click',()=>{delete state.comparisons[group()+'-'+el.dataset.resetPhrase];render(false);}));
}
function bindPractice(){const q=bank()[selectedQuestion];const get=()=>state.answers[q.id]||(state.answers[q.id]={value:'',chunks:[]});on('questionSelect','change',e=>{selectedQuestion=Number(e.target.value);render(false);});on('practiceText','input',e=>{if(q.kind==='order')get().typed=e.target.value;else get().value=e.target.value;persist();});document.querySelectorAll('input[name="practiceAnswer"]').forEach(el=>el.addEventListener('change',()=>{get().value=el.value;persist();}));document.querySelectorAll('[data-chunk]').forEach(el=>el.addEventListener('click',()=>{const a=get(),i=Number(el.dataset.chunk);if(a.checked||(a.chunks||[]).includes(i))return;a.chunks.push(i);render(false);}));on('undoChunk','click',()=>{if(get().checked)return;get().chunks.pop();render(false);});on('clearChunks','click',()=>{if(get().checked)return;get().chunks=[];get().typed='';render(false);});
 on('checkAnswer','click',()=>{const a=get();if(a.checked)return;const value=q.kind==='order'?(a.typed?.trim()||a.chunks.map(i=>q.answers[0].split(' ')[i]).join(' ')):a.value;if(!value?.trim()){$('practiceValidation').textContent='Unanswered — enter or choose an answer first. No attempt has been recorded.';announce($('practiceValidation').textContent);return;}a.correct=E.answerMatches(value,q.answers);a.checked=true;if(!a.attempted){a.firstCorrect=a.correct;a.attempted=true;}persist();render(false);announce(a.correct?'Correct. Explanation ready.':'Not quite. Compare the accepted answer and explanation, then try again.');});
 on('tryAgain','click',()=>{get().checked=false;get().value='';get().typed='';get().chunks=[];render(false);});on('clearAnswer','click',()=>{get().checked=false;get().value='';get().typed='';get().chunks=[];render(false);});on('resetActivity','click',()=>{delete state.answers[q.id];render(false);announce('Only this activity answer and recorded attempt were reset.');});on('showHint','click',()=>{$('practiceHint').hidden=false;announce(q.hint);});on('prevQuestion','click',()=>{selectedQuestion--;render(false);});on('nextQuestion','click',()=>{selectedQuestion++;render(false);});}
async function copyText(text){try{await navigator.clipboard.writeText(text);if($('copyStatus'))$('copyStatus').textContent='Writing copied.';announce('Writing copied.');}catch(e){if($('draftText')){$('draftText').focus();$('draftText').select();$('copyStatus').textContent='Clipboard access is unavailable. Your writing is selected; use your device’s copy command or Download writing.';}announce('Use your device copy command or download the writing.');}}
function remaining(){return state.timer.running?Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000)):state.timer.remaining;}
function formatTime(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function bindTimer(){const applyMinutes=e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>120){if(e.type==='change'){e.target.value=state.timer.minutes;announce('Choose a whole number from 1 to 120 minutes.');}return;}state.timer.minutes=n;state.timer.remaining=n*60;state.timer.running=false;state.timer.deadline=null;persist();$('timerDisplay').textContent=formatTime(n*60);$('timerStart').textContent='Start / resume';$('timerStatus').textContent=state.timer.untimed?'Untimed mode':'Paused / ready';};on('timerMinutes','input',applyMinutes);on('timerMinutes','change',applyMinutes);on('timerStart','click',()=>{const t=state.timer;if(t.untimed){announce('Untimed mode is on. Turn it off to start a countdown.');return;}if(t.running){t.remaining=remaining();t.running=false;t.deadline=null;announce('Timer paused.');}else{if(t.remaining<=0)t.remaining=t.minutes*60;t.running=true;t.deadline=Date.now()+t.remaining*1000;announce('Timer started. Your writing will not be submitted or locked automatically.');}persist();render(false);});on('timerReset','click',()=>{state.timer.running=false;state.timer.deadline=null;state.timer.remaining=state.timer.minutes*60;persist();render(false);announce('Timer reset. Writing is unchanged.');});on('untimed','change',e=>{state.timer.remaining=remaining();state.timer.untimed=e.target.checked;state.timer.running=false;state.timer.deadline=null;persist();render(false);announce(e.target.checked?'Untimed mode enabled.':'Countdown available.');});}
function tick(){const n=remaining();if($('timerDisplay'))$('timerDisplay').textContent=formatTime(n);if(state.timer.running&&n<=0){state.timer.running=false;state.timer.deadline=null;state.timer.remaining=0;persist();if($('timerStart'))$('timerStart').textContent='Start again';if($('timerStatus'))$('timerStatus').textContent='Time finished · keep writing';announce('Your timer has finished. You can continue writing; nothing has been submitted or cleared.');}}
function exportReport(){const lines=['Stage 11 practice summary — no writing grade',new Date().toLocaleString()];for(const genre of ['essay','biography'])for(const path of ['foundation','core','challenge']){const qs=E.makeBank(genre,path),attempted=qs.filter(q=>state.answers[q.id]?.attempted);lines.push(`${D.genres[genre].name} / ${path}: ${attempted.length}/${qs.length} attempted; ${attempted.filter(q=>state.answers[q.id]?.firstCorrect).length}/${attempted.length} correct on first attempt.`);}const reviewEntries=Object.entries(state.answers).filter(([k,a])=>k.startsWith('review-')&&a.attempted);lines.push(`Review quizzes: ${reviewEntries.length} attempted; ${reviewEntries.filter(([k,a])=>a.firstCorrect).length} correct on first attempt.`);for(const g of Object.values(D.genres))for(const p of g.prompts){const d=state.drafts[p.id];if(d?.text.trim())lines.push(`${g.name}: ${p.text} — ${d.versions.length} submitted versions; ${E.countWords(d.text)} words (not a quality score).`);}download('stage11-practice-summary.txt',lines.join('\n'));}
async function importBackup(e){const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Backup exceeds 10 MB.');const raw=await file.text();if(/"(?:__proto__|constructor|prototype)"\s*:/.test(raw))throw Error('Unsafe backup key.');const incoming=JSON.parse(raw);if(!E.validateState(incoming))throw Error('This is not a supported version-3 studio backup.');for(const collection of ['drafts','plans','answers','vocabulary','comparisons','development','reflections','visited'])for(const [k,v]of Object.entries(incoming[collection])){if(collection==='drafts'&&state.drafts[k]?.updatedAt>v.updatedAt)continue;state[collection][k]=v;}state.settings=incoming.settings;state.timer={...incoming.timer,running:false,deadline:null};storageOK=true;recoveryMessage='';persist();render(false);$('importStatus').textContent='Backup restored. Newer current drafts were kept.';announce('Backup restored.');}catch(error){$('importStatus').textContent='Backup not restored: '+error.message;announce($('importStatus').textContent);}}
$('closeExport').addEventListener('click',()=>$('exportDialog').close());$('selectExport').addEventListener('click',()=>{$('exportText').focus();$('exportText').select();announce('Export text selected. Use your device copy command.');});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();$('main').focus();$('main').scrollIntoView({block:'start'});});
load();$('genre').addEventListener('change',e=>{state.settings.genre=e.target.value;history.replaceState(null,'','#'+location.hash.slice(1).split('?')[0]);lastRouteHash=location.hash;delete state.settings.prompt;state.settings.unit=currentGenre().unitId||'u2';selectedQuestion=0;selectedWord=0;render(false);announce('Genre changed. Your other drafts remain saved.');});$('pathway').addEventListener('change',e=>{state.settings.pathway=e.target.value;selectedQuestion=0;render(false);announce('Pathway changed. Your writing is kept.');});$('backup').addEventListener('click',backup);window.addEventListener('hashchange',()=>render());window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){storageOK=false;recoveryMessage='Another tab changed the saved studio work. Saving in this tab is paused to avoid overwriting it. Export this tab’s work before reloading.';$('saveStatus').textContent='Another tab saved · export before reloading';announce(recoveryMessage);}});window.addEventListener('pagehide',()=>{state.timer.remaining=remaining();persist();});setInterval(tick,500);render(false);
})();
